// Minimal hash table with separate chaining
class HashMap {
  #buckets;
  #size = 0;
  #capacity;
  static LOAD_FACTOR = 0.75;

  constructor(capacity = 16) {
    this.#capacity = capacity;
    this.#buckets  = Array.from({ length: capacity }, () => []);
  }

  // Polynomial rolling hash — prime 31 spreads bits, >>> 0 keeps 32-bit unsigned
  #hash(key) {
    let h = 0;
    for (let i = 0; i < key.length; i++)
      h = (h * 31 + key.charCodeAt(i)) >>> 0;
    return h % this.#capacity;
  }

  set(key, value) {                              // O(1) amortised
    const idx   = this.#hash(key);
    const chain = this.#buckets[idx];
    const entry = chain.find(e => e[0] === key);
    if (entry) { entry[1] = value; return; }     // update existing
    chain.push([key, value]);                    // new entry
    this.#size++;
    if (this.#size / this.#capacity > HashMap.LOAD_FACTOR)
      this.#rehash();
  }

  get(key) {                                     // O(1) avg
    const chain = this.#buckets[this.#hash(key)];
    return chain.find(e => e[0] === key)?.[1];
  }

  has(key) {
    const chain = this.#buckets[this.#hash(key)];
    return chain.some(e => e[0] === key);
  }

  delete(key) {                                  // O(1) avg
    const idx   = this.#hash(key);
    const chain = this.#buckets[idx];
    const i     = chain.findIndex(e => e[0] === key);
    if (i === -1) return false;
    chain.splice(i, 1);
    this.#size--;
    return true;
  }

  #rehash() {                                    // O(n) — triggered rarely
    this.#capacity *= 2;
    const old = this.#buckets;
    this.#buckets = Array.from({ length: this.#capacity }, () => []);
    this.#size = 0;
    for (const chain of old)
      for (const [k, v] of chain) this.set(k, v);
    // Note: set() is called again — indices change because capacity doubled
  }

  get size() { return this.#size; }

  // Iteration — chains in bucket order
  *entries() {
    for (const chain of this.#buckets)
      for (const entry of chain) yield entry;
  }
}

// Usage
const map = new HashMap();
map.set('alice', 30);
map.set('bob',   25);
map.set('carol', 28);
map.set('alice', 31);              // update — replaces 30 with 31
console.log(map.get('alice'));     // 31
console.log(map.get('dave'));      // undefined
console.log(map.has('bob'));       // true
map.delete('bob');
console.log(map.size);             // 2

for (const [k, v] of map.entries())
  console.log(k, v);              // alice 31 / carol 28 (bucket order)

// ── Classic interview patterns using hash tables ──────────────

// Pattern 1: Two Sum — O(n) time, O(n) space
// For each element, check if its complement is already seen
function twoSum(nums, target) {
  const seen = new Map();           // value → index
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement))
      return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
console.log(twoSum([2, 7, 11, 15], 9));   // [0, 1]
console.log(twoSum([3, 2, 4], 6));         // [1, 2]

// Pattern 2: Frequency counter — O(n) time and space
// Count occurrences of each element
function mostFrequent(arr) {
  const freq = new Map();
  for (const x of arr) freq.set(x, (freq.get(x) ?? 0) + 1);
  let best = null, bestCount = 0;
  for (const [val, count] of freq) {
    if (count > bestCount) { best = val; bestCount = count; }
  }
  return best;
}
console.log(mostFrequent([1, 2, 2, 3, 3, 3])); // 3

// Pattern 3: Group anagrams — O(n*k) where k = avg word length
// Keys: sorted characters of each word (canonical form)
function groupAnagrams(words) {
  const groups = new Map();
  for (const word of words) {
    const key = word.split('').sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(word);
  }
  return [...groups.values()];
}
console.log(groupAnagrams(['eat','tea','tan','ate','nat','bat']));
// [['eat','tea','ate'],['tan','nat'],['bat']]

// Pattern 4: First non-repeating character — two-pass O(n)
function firstUnique(s) {
  const freq = new Map();
  for (const c of s) freq.set(c, (freq.get(c) ?? 0) + 1);
  for (let i = 0; i < s.length; i++)
    if (freq.get(s[i]) === 1) return i;
  return -1;
}
console.log(firstUnique('leetcode'));  // 0 ('l')
console.log(firstUnique('aabb'));      // -1
